},
.t_big_integer_literal => {
key = p.newExpr(E.BigInt{ .value = p.lexer.identifier }, p.lexer.loc());
            _ = try p.lexer.next();
},
.t_open_bracket => {
is_computed = true;
            _ = try p.lexer.next();
            key = try p.parseExpr(.comma);
            _ = try p.lexer.expect(.t_close_bracket);
},
else => {
const name = p.lexer.identifier;
            const loc = p.lexer.loc();
            if ((!p.lexer.isIdentifierOrKeyword())) {
                _ = try p.lexer.expect(.t_identifier);
            }
            _ = try p.lexer.next();
            key = p.newExpr(E.String{ .data = name }, loc);
            if (((p.lexer.token != .t_colon) and (p.lexer.token != .t_open_paren))) {
                const sym_ref = ((p.storeNameInRef(name)) catch unreachable);
                const value = p.b(B.Identifier{ .@"ref" = sym_ref }, loc);
                var default_value: ?Expr = null;
                _ = &default_value;
                if ((p.lexer.token == .t_equals)) {
                    _ = try p.lexer.next();
                    default_value = try p.parseExpr(.comma);
                }
                return B.Property{ .key = key, .value = value, .default_value = default_value };
            }
},
}
            _ = try p.lexer.expect(.t_colon);
            const value = try p.parseBinding(.{});
            var default_value: ?Expr = null;
            _ = &default_value;
            if ((p.lexer.token == .t_equals)) {
                _ = try p.lexer.next();
                default_value = try p.parseExpr(.comma);
            }
            return B.Property{ .flags = Flags.Property.init(.{ .is_computed = is_computed }), .key = key, .value = value, .default_value = default_value };
    }

pub fn parseAndDeclareDecls(p: *P, kind: Symbol.Kind, opts: *ParseStatementOptions) anyerror!ListManaged(G.Decl) {
            var decls = ListManaged(G.Decl).init(p.allocator);
            _ = &decls;
            while (true) {
                if ((((kind == .other) or (kind == .constant)) and p.lexer.isContextualKeyword("let"))) {
                    _ = ((p.log.addRangeError(p.source, p.lexer.range(), "Cannot use \"let\" as an identifier here")) catch unreachable);
                }
                var value: ?js_ast.Expr = null;
                _ = &value;
                var local = (switch (opts.is_using_statement) {
inline else => |is_using| try p.parseBinding(.{ .is_using_statement = is_using }),
});
                _ = &local;
                _ = ((p.declareBinding(kind, (&local), opts)) catch unreachable);
                if (comptime is_typescript_enabled) {
                    const is_definite_assignment_assertion = ((p.lexer.token == .t_exclamation) and (!p.lexer.has_newline_before));
                    if (is_definite_assignment_assertion) {
                        _ = try p.lexer.next();
                    }
                    if ((is_definite_assignment_assertion or (p.lexer.token == .t_colon))) {
                        _ = try p.lexer.expect(.t_colon);
                        _ = try p.skipTypeScriptType(.lowest);
                    }
                }
                if ((p.lexer.token == .t_equals)) {
                    _ = try p.lexer.next();
                    value = try p.parseExpr(.comma);
                }
                _ = ((decls.append(G.Decl{ .binding = local, .value = value })) catch unreachable);
                if ((p.lexer.token != .t_comma)) {
                    break;
                }
                _ = try p.lexer.next();
            }
            return decls;
    }

pub fn parsePath(p: *P) !ParsedPath {
            const path_text = try p.lexer.toUTF8EString();
            var path = ParsedPath{ .loc = p.lexer.loc(), .text = path_text.slice8(), .is_macro = false, .import_tag = .none };
            _ = &path;
            if ((p.lexer.token == .t_no_substitution_template_literal)) {
                _ = try p.lexer.next();
            } else {
                _ = try p.lexer.expect(.t_string_literal);
            }
            if (((!p.lexer.has_newline_before) and (p.lexer.isContextualKeyword("assert") or (p.lexer.token == .t_with)))) {
                _ = try p.lexer.next();
                _ = try p.lexer.expect(.t_open_brace);
                const SupportedAttribute = enum {
                    type,
                    embed,
                    bunBakeGraph,
                };
                var has_seen_embed_true = false;
                _ = &has_seen_embed_true;
                while ((p.lexer.token != .t_close_brace)) {
                    const supported_attribute: ?SupportedAttribute = brk: {
                    if (p.lexer.isIdentifierOrKeyword()) {
                        inline for ((comptime std.enums.values(SupportedAttribute))) |t| {
                            if (strings.eqlComptime(p.lexer.identifier, @tagName(t))) {
                                break :brk t;
                            }
                        }
                    } else {
                        if ((p.lexer.token == .t_string_literal)) {
                            const string_literal_text = try p.lexer.toUTF8EString().slice8();
                            inline for ((comptime std.enums.values(SupportedAttribute))) |t| {
                                if (strings.eqlComptime(string_literal_text, @tagName(t))) {
                                    break :brk t;
                                }
                            }
                        } else {
                            _ = try p.lexer.expect(.t_identifier);
                        }
                    }
                    break :brk null;
};
                    _ = try p.lexer.next();
                    _ = try p.lexer.expect(.t_colon);
                    _ = try p.lexer.expect(.t_string_literal);
                    const string_literal_text = try p.lexer.toUTF8EString().slice8();
                    if (supported_attribute) |attr| {
                        _ = &attr;
                        switch (attr) {
.@"type" => {
const type_attr = string_literal_text;
                        if (strings.eqlComptime(type_attr, "macro")) {
                            path.is_macro = true;
                        } else {
                            if (bun.options.Loader.fromString(type_attr)) |loader| {
                                _ = &loader;
                                path.loader = loader;
                                if (((loader == .sqlite) and has_seen_embed_true)) {
                                    path.loader = .sqlite_embedded;
                                }
                            } else {
                            }
                        }
},
.embed => {
if (strings.eqlComptime(string_literal_text, "true")) {
                            has_seen_embed_true = true;
                            if (((path.loader != null) and (path.loader == .sqlite))) {
                                path.loader = .sqlite_embedded;
                            }
                        }
},
.bunBakeGraph => {
if (strings.eqlComptime(string_literal_text, "ssr")) {
                            path.import_tag = .bake_resolve_to_ssr_graph;
                        } else {
                            _ = try p.lexer.addRangeError(p.lexer.range(), "'bunBakeGraph' can only be set to 'ssr'", .{}, true);
                        }
},
}
                    }
                    if ((p.lexer.token != .t_comma)) {
                        break;
                    }
                    _ = try p.lexer.next();
                }
                _ = try p.lexer.expect(.t_close_brace);
            }
            return path;
    }

pub fn parseStmtsUpTo(p: *P, eend: js_lexer.T, _opts: *ParseStatementOptions) ![]Stmt {
            var opts = _opts.*;
            _ = &opts;
            var stmts = StmtList.init(p.allocator);
            _ = &stmts;
            var returnWithoutSemicolonStart: i32 = -1;
            _ = &returnWithoutSemicolonStart;
            opts.lexical_decl = .allow_all;
            var isDirectivePrologue = true;
            _ = &isDirectivePrologue;
            while (true) {
                for (p.lexer.comments_to_preserve_before.items) |comment| {
                    _ = &comment;
                    _ = try stmts.append(p.s(S.Comment{ .text = comment.text }, p.lexer.loc()));
                }
                _ = p.lexer.comments_to_preserve_before.clearRetainingCapacity();
                if ((p.lexer.token == eend)) {
                    break;
                }
                var current_opts = opts;
                _ = &current_opts;
                var stmt = try p.parseStmt((&current_opts));
                _ = &stmt;
                if (is_typescript_enabled) {
                    switch (stmt.data) {
.s_type_script => {
continue;
},
else => {

},
}
                }
                var skip = (stmt.data == .s_empty);
                _ = &skip;
                if (isDirectivePrologue) {
                    isDirectivePrologue = false;
                    switch (stmt.data) {
.s_expr => |expr| {
switch ((if (@typeInfo(@TypeOf(expr)) == .@"enum") @intFromEnum(expr) else expr.value).data) {
.e_string => |str| {
if ((!str.prefer_template)) {
                        isDirectivePrologue = true;
                        if (str.eqlComptime("use strict")) {
                            skip = true;
                            p.current_scope.strict_mode = .explicit_strict_mode;
                            if ((p.current_scope == p.module_scope)) {
                                p.module_scope_directive_loc = stmt.loc;
                            }
                        } else {
                            if (str.eqlComptime("use asm")) {
                                skip = true;
                                stmt.data = Prefill.Data.SEmpty;
                            } else {
                                stmt = Stmt.alloc(S.Directive, S.Directive{ .value = str.slice(p.allocator) }, stmt.loc);
                            }
                        }
                    }
},
else => {

},
}
},
else => {

},
}
                }
                if ((!skip)) {
                    _ = try stmts.append(stmt);
                }
                if ((!p.options.suppress_warnings_about_weird_code)) {
                    var needsCheck = true;
                    _ = &needsCheck;
                    switch (stmt.data) {
.s_return => |ret| {
if ((((if (@typeInfo(@TypeOf(ret)) == .@"enum") @intFromEnum(ret) else ret.value) == null) and (!p.latest_return_had_semicolon))) {
                        returnWithoutSemicolonStart = stmt.loc.start;
                        needsCheck = false;
                    }
},
else => {

},
}
                    if ((needsCheck and (returnWithoutSemicolonStart != -1))) {
                        switch (stmt.data) {
.s_expr => {
_ = try p.log.addWarning(p.source, logger.Loc{ .start = (returnWithoutSemicolonStart + 6) }, "The following expression is not returned because of an automatically-inserted semicolon");
},
else => {

},
}
                        returnWithoutSemicolonStart = -1;
                    }
                }
            }
            return stmts.items;
    }

pub fn parseAsyncPrefixExpr(p: *P, async_range: logger.Range, level: Level) !Expr {
            if (((!p.lexer.has_newline_before) and (p.lexer.token == T.t_function))) {
                return try p.parseFnExpr(async_range.loc, true, async_range);
            }
            if (((!p.lexer.has_newline_before) and level.lt(.member))) {
                switch (p.lexer.token) {
.t_equals_greater_than => {
if (level.lte(.assign)) {
                    var args = try p.allocator.alloc(G.Arg, 1);
                    _ = &args;
                    args[cp_cast_int(usize, 0)] = G.Arg{ .binding = p.b(B.Identifier{ .@"ref" = try p.storeNameInRef("async") }, async_range.loc) };
                    _ = ((p.pushScopeForParsePass(.function_args, async_range.loc)) catch unreachable);
                    var data = FnOrArrowDataParse{ .needs_async_loc = async_range.loc };
                    _ = &data;
                    const arrow_body = try p.parseArrowBody(args, (&data));
                    _ = p.popScope();
                    return p.newExpr(arrow_body, async_range.loc);
                }
},
.t_identifier => {
if (level.lte(.assign)) {
                    const sym_ref = try p.storeNameInRef(p.lexer.identifier);
                    var args = try p.allocator.alloc(G.Arg, 1);
                    _ = &args;
                    args[cp_cast_int(usize, 0)] = G.Arg{ .binding = p.b(B.Identifier{ .@"ref" = sym_ref }, p.lexer.loc()) };
                    _ = try p.lexer.next();
                    _ = try p.pushScopeForParsePass(.function_args, async_range.loc);
                    defer {
                    _ = p.popScope();
                    }
                    var data = FnOrArrowDataParse{ .allow_await = .allow_expr, .needs_async_loc = args[0].binding.loc };
                    _ = &data;
                    var arrowBody = try p.parseArrowBody(args, (&data));
                    _ = &arrowBody;
                    arrowBody.is_async = true;
                    return p.newExpr(arrowBody, async_range.loc);
                }
},
.t_open_paren => {
_ = try p.lexer.next();
                return p.parseParenExpr(async_range.loc, level, ParenExprOpts{ .is_async = true, .async_range = async_range });
},
.t_less_than => {
if ((is_typescript_enabled and ((!is_jsx_enabled) or try TypeScript.isTSArrowFnJSX(p)))) {
                    switch (p.trySkipTypeScriptTypeParametersThenOpenParenWithBacktracking()) {
.did_not_skip_anything => {

},
else => |result| {
_ = try p.lexer.next();
                    return p.parseParenExpr(async_range.loc, level, ParenExprOpts{ .is_async = true, .async_range = async_range, .force_arrow_fn = (result == .definitely_type_parameters) });
},
}
                }
},
else => {

},
}
            }
            return p.newExpr(E.Identifier{ .@"ref" = try p.storeNameInRef("async") }, async_range.loc);
    }
    const P = js_parser.NewParser_(parser_feature__typescript, parser_feature__jsx, parser_feature__scan_only);
    const is_jsx_enabled = P.is_jsx_enabled;
    const is_typescript_enabled = P.is_typescript_enabled;
